#!/bin/bash
set -euo pipefail

# Advisory routing, not a shell parser or proof that visual evidence is complete.
# Successful-hook context must be in stdout JSON, not debug-only stderr.
command=$(jq -r '.tool_input.command // empty' | tr -d "\\\\\"'")
if printf '%s' "$command" | grep -qE '(^|[[:space:];|&/])(gh[[:space:]]+((--repo|-R|--hostname)[=[:space:]]+[^[:space:]]+[[:space:]]+)*(pr[[:space:]]+(create|edit|reopen|ready)|stack[[:space:]]+submit)|git[[:space:]]+push)([[:space:];|&]|$)'; then
  jq -nc --arg context '[pr-evidence] Before publication, follow commit-push-pr/REFERENCE.md and shared/verifiability.md#proportionate-verification: smallest functional diff, existing checks first, new regressions only for credible uncovered risk. Reconcile an existing session PR with its full diff, value, decisive results and material limits; re-read the hosted body after updates. Inspect affected rendering. UI PR publication follows pr/SKILL.md: comparable before/after table, or explain an unavailable/inapplicable comparison; reuse existing visual-test evidence. Verification depth stays risk-based; stronger project checks still apply. Backend/API/Protobuf/frontend-backend contract, architecture, data-flow or workflow changes without explanatory screenshots/video require a source-grounded diagram (excalidraw-diagram/PR-WORKFLOW.md); prefer Excalidraw, fall back to inline Mermaid on rendering/upload failure. Mixed changes still need diagrams for unexplained non-UI contracts. The lifecycle Stop gate requires hosted visual evidence or Visual evidence: not applicable — <concrete reason> for changes outside that scope. The general visual check covers presence, not the UI table, revision freshness, access, real-app verification, accuracy or skip eligibility; a gate pass is not a visual-review PASS. Every consumer/end-user-facing UI PR in every consuming repository (including mixed PRs and follow-ups) must load package-my-work, publish a current packaged recording, and include UI packaging: <hosted recording URL>. Screenshots/diagrams cannot substitute for it. Non-UI PRs declare UI packaging: not applicable — <concrete non-UI reason>; an actual owner waiver uses UI packaging: waived — <reason>; approval: <reference>. Review-only stays read-only; local/commit/push endpoints retain publication stops. The completion gate checks declarations/links, not UI-scope truth, media type or playback. Annotations, reports and new visual runners remain conditional. Keep logs/captures temporary and summarize inline. Reuse existing consuming-repo safeguards; add files only for a concrete in-scope need. Preserve hosted policy and approval counts; missing required checks/access is not green. Push alone never authorizes PR creation.' \
    '{hookSpecificOutput:{hookEventName:"PreToolUse",additionalContext:$context}}'
fi
